export const getUpdateTransportDriverLocationUrl = (id: string,) => {




  return `/api/transport/drivers/${id}/location`
}

/**
 * @summary Update the authenticated driver's own GPS position
 */
export const updateTransportDriverLocation = async (id: string,
    transportDriverLocationInput: TransportDriverLocationInput, options?: Parameters<typeof customFetch>[1]): Promise<TransportDriver> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Array.isArray(h)) return Object.fromEntries(h);
    return h;
  };
return customFetch<TransportDriver>(getUpdateTransportDriverLocationUrl(id),
  {
    ...options,
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(transportDriverLocationInput)
  }
);}





